// Bundles docs/legal/*.md into legal-content.generated.ts so the public pages ship with the app
// build (Metro cannot import .md files). Run after editing a legal document:
//   node apps/mobile/src/features/public/generate-legal.mjs
// A test (markdown.test.ts) fails when the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import prettier from 'prettier';

const here = dirname(fileURLToPath(import.meta.url));
const legalDir = join(here, '..', '..', '..', '..', '..', 'docs', 'legal');
const outFile = join(here, 'legal-content.generated.ts');

export async function buildLegalSource() {
  const slugs = readdirSync(legalDir)
    .filter((f) => f.endsWith('.md'))
    .map((f) => f.slice(0, -3))
    .sort();
  const entries = slugs.map((slug) => {
    const text = readFileSync(join(legalDir, `${slug}.md`), 'utf8').replace(/\r\n/g, '\n');
    return `  ${JSON.stringify(slug)}: ${JSON.stringify(text)},`;
  });
  const source = [
    '// GENERATED by generate-legal.mjs from docs/legal/*.md. Do not edit by hand.',
    'export const LEGAL_MARKDOWN: Record<string, string> = {',
    ...entries,
    '};',
    '',
  ].join('\n');
  const options = (await prettier.resolveConfig(outFile)) ?? {};
  return prettier.format(source, { ...options, filepath: outFile });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(outFile, await buildLegalSource());
  console.log(`wrote ${outFile}`);
}
